import{_ as t,o,c as a,ai as s}from"./chunks/framework.Cabe_Szf.js";const p=JSON.parse('{"title":"Shared box","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/shared-box.md","filePath":"en/guide/shared-box.md","lastUpdated":1792109577000}'),h={name:"en/guide/shared-box.md"};function n(r,e,i,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="shared-box" tabindex="-1">Shared box <a class="header-anchor" href="#shared-box" aria-label="Permalink to &quot;Shared box&quot;">​</a></h1><p>The <strong>Shared box</strong> page answers one question: why is Ollama slow right now, and which of my tools did it. It lists what each tool asked the daemon for and what that cost the other tools, in seconds, with the setting to change.</p><p><strong>Sidebar item:</strong> Shared box (below Prompt X-ray) <strong>Route:</strong> <code>/shared-box</code><strong>Added in:</strong> v0.8.0 (October 2026) <strong>Requires:</strong> turns on the Live page from more than one tool. With one tool there is nobody to cost anything.</p><h2 id="what-s-the-point" tabindex="-1">What&#39;s the point? <a class="header-anchor" href="#what-s-the-point" aria-label="Permalink to &quot;What&#39;s the point?&quot;">​</a></h2><p>Ollama serves whatever arrives and never says who made it slow. Three settings travel inside requests and change the daemon&#39;s state for everyone:</p><ul><li><code>keep_alive</code>. A tool that sends <code>keep_alive: 0</code> unloads the model after each of its requests. The next tool to arrive pays the reload, often tens of seconds.</li><li><code>num_ctx</code>. The daemon reserves the whole context window up front. A tool that asks for a 128 000-token context on 4 000-token prompts takes several gigabytes for itself, and the daemon drops from several requests at a time to one.</li><li>Model switches. A tool that brings in a different model unloads the one the others were using.</li></ul><p>None of this is reported by Ollama. The observe port sees every request, so it can keep the ledger.</p><h2 id="the-one-sentence" tabindex="-1">The one sentence <a class="header-anchor" href="#the-one-sentence" aria-label="Permalink to &quot;The one sentence&quot;">​</a></h2><p>At the top: how many tools, how many models, over what span, and what their settings cost the others. If the answer is nothing, the page says so.</p><h2 id="who-cost-whom" tabindex="-1">Who cost whom <a class="header-anchor" href="#who-cost-whom" aria-label="Permalink to &quot;Who cost whom&quot;">​</a></h2><p>One row per tool, sorted by the time taken from the others. Each row says, in plain words, what the tool asked for and what that cost, then the fix as the exact setting to change. A tool that cost nothing is listed too, in green, so you can see what good looks like.</p><p>What a tool costs itself is shown but never counted against it.</p><h2 id="how-the-costs-are-attributed" tabindex="-1">How the costs are attributed <a class="header-anchor" href="#how-the-costs-are-attributed" aria-label="Permalink to &quot;How the costs are attributed&quot;">​</a></h2><p>The rules are simple enough to state, and the page states them:</p><ul><li>A model (re)load is charged to whoever unloaded the model. If the previous request to the same model asked for <code>keep_alive: 0</code>, that tool caused it. If another model was used in between, the tool that brought that model in caused it. Otherwise the model sat idle longer than <code>keep_alive</code>, and the reload is nobody&#39;s fault.</li><li>A wait is charged to whichever request the daemon was still serving when this one arrived.</li></ul><h2 id="how-many-tools-at-once" tabindex="-1">How many tools at once <a class="header-anchor" href="#how-many-tools-at-once" aria-label="Permalink to &quot;How many tools at once&quot;">​</a></h2><p>Ollama serves several requests at the same time only while they fit in video memory. When a tool reserves a large context, the daemon quietly drops to fewer at a time. It does not say so anywhere; the page reads it from the loaded context the daemon reports against the context each request asked for, and lists the moment the count fell and which tool&#39;s request did it.</p><h2 id="what-happened-in-order" tabindex="-1">What happened, in order <a class="header-anchor" href="#what-happened-in-order" aria-label="Permalink to &quot;What happened, in order&quot;">​</a></h2><p>Every load and every wait, with the time, the tool that paid, and who caused it when another tool did.</p><h2 id="what-the-page-does-not-know" tabindex="-1">What the page does not know <a class="header-anchor" href="#what-the-page-does-not-know" aria-label="Permalink to &quot;What the page does not know&quot;">​</a></h2><p>Anything that did not pass through the observe port. A tool that talks to Ollama directly on 11434 is invisible here, which is worth knowing when the numbers do not add up. The queue wait is our wall time minus the daemon&#39;s own total, so it is an estimate.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live.html">Live</a> records the turns.</li><li><a href="./gpu-map.html">GPU map</a> shows what the reserved contexts take in video memory.</li></ul>',23)])])}const u=t(h,[["render",n]]);export{p as __pageData,u as default};
